/**
 * Regenerates src/lib/emoji-pool.generated.ts from Unicode's emoji list:
 * fully-qualified emoji only, minus skin-tone variants, flags/tag sequences
 * and the EMOJI_DENYLIST. Run `npm run emoji:generate` when Unicode updates;
 * the generated file is committed like any other source file.
 */
import { writeFileSync } from 'node:fs';
import { EMOJI_DENYLIST } from '../src/lib/thinking-content.js';

const SOURCE = 'https://unicode.org/Public/emoji/latest/emoji-test.txt';
const OUT = 'src/lib/emoji-pool.generated.ts';

const response = await fetch(SOURCE);
if (!response.ok) throw new Error(`Could not fetch ${SOURCE}: ${response.status}`);
const text = await response.text();

const denied = new Set(EMOJI_DENYLIST);
const seen = new Set<string>();
const emoji: string[] = [];
let version = 0;
let versionLabel = 'unknown';

for (const line of text.split('\n')) {
  if (!line.includes('; fully-qualified')) continue;
  const rest = line.slice(line.indexOf('#') + 1).trim();
  const match = /^(\S+)\s+(E\d+\.\d+)\s+/.exec(rest);
  if (match === null) continue;
  const glyph = match[1]!;
  const name = rest.slice(match[0].length);
  if (name.includes('skin tone')) continue;
  if (name.startsWith('flag: ') || name.startsWith('tag: ') || name.startsWith('subdivision-flag: ')) continue;
  if (denied.has(glyph) || seen.has(glyph)) continue;
  seen.add(glyph);
  emoji.push(glyph);
  const value = Number.parseFloat(match[2]!.slice(1));
  if (value > version) {
    version = value;
    versionLabel = match[2]!;
  }
}

const perLine = 14;
const rows: string[] = [];
for (let i = 0; i < emoji.length; i += perLine) {
  rows.push(`  ${emoji.slice(i, i + perLine).map((e) => `'${e}'`).join(', ')},`);
}

const file = `/**
 * The full emoji pool for lone-emoji moments: every fully-qualified emoji,
 * minus skin-tone variants, flags and the denylist in thinking-content.ts.
 * Generated by \`npm run emoji:generate\` — do not edit by hand.
 *
 * Source: ${SOURCE} (newest entry: ${versionLabel})
 * Generated: ${new Date().toISOString().slice(0, 10)} · ${emoji.length} emoji
 */
export const EMOJI_POOL: readonly string[] = [
${rows.join('\n')}
];
`;

writeFileSync(OUT, file);
console.log(`Wrote ${OUT}: ${emoji.length} emoji (newest ${versionLabel}).`);
